-- Vuelta atras de la carta 2026.
--
-- NO es una migracion y no va en db/migration: es un archivo suelto para
-- correr a mano con psql si el menu 2026 resulta equivocado y hay que
-- devolver la carta que estaba antes.
--
-- Contiene la carta de comida exactamente como la respondia el API el
-- 21 de agosto de 2026, antes de aplicar V9: siete categorias y cuarenta
-- y dos platos, con sus mismos identificadores, precios y modificadores.
--
-- Las bebidas no aparecen aqui porque V9 no las toco.
--
--   psql "$DATABASE_URL" -f carta-anterior-20260821.sql

-- Fuera la carta 2026.
DELETE FROM items_carta WHERE categoria_id IN ('entradas', 'carnes', 'pescados-y-mariscos', 'pastas-artesanales', 'aves', 'arroces', 'picada', 'express', 'infantil', 'postre');
DELETE FROM categorias_carta WHERE id IN ('entradas', 'carnes', 'pescados-y-mariscos', 'pastas-artesanales', 'aves', 'arroces', 'picada', 'express', 'infantil', 'postre');

-- Las bebidas vuelven a su puesto original.
UPDATE categorias_carta SET orden = 8 WHERE id = 'c8';  -- Coctelería de autor
UPDATE categorias_carta SET orden = 9 WHERE id = 'c9';  -- Coctelería clásica
UPDATE categorias_carta SET orden = 10 WHERE id = 'c10';  -- Cervezas y bebidas

